  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Determines whether a booking can be created for the given customer, trip, and booking date.
   * Algorithm:
   *   1. If customer is null or trip is null or bookingDate is null → return false.
   *   2. If numberOfSeats <= 0 or numberOfSeats > trip.numberOfSeats → return false.
   *   3. Parse trip.departureTime and trip.arrivalTime as datetime strings in format yyyy-MM-dd HH:mm.
   *      If parsing fails → return false.
   *   4. If the difference between trip.departureTime and bookingDate (as datetime) is less than or equal to 2 hours → return false.
   *   5. For each existing booking b in customer.bookings:
   *      - If b.trip is not null and b.trip.departureTime and b.trip.arrivalTime are valid:
   *        - If b.trip.departureTime and b.trip.arrivalTime are on the same calendar day as trip's departureTime:
   *          - If b.trip.departureTime < trip.arrivalTime and trip.departureTime < b.trip.arrivalTime → return false.
   *   6. Return true.
   * Related Features: customer, trip, bookingDate, numberOfSeats, trip.numberOfSeats, trip.departureTime, trip.arrivalTime, customer.bookings
   * Related Classes: Customer, Trip, EDate
   * Input: None (uses instance fields: customer, trip, bookingDate, numberOfSeats)
   * Output: boolean - true if the booking is eligible, false otherwise.
   * Pre-condition: None
   * Post-condition: No state changes. Returns eligibility result.
   * <!-- end-model-doc -->
   * @model kind="operation"
   *        annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean isBookingEligible()
  {
    // Step 1: Check for null values
    if (getCustomer() == null || getTrip() == null || getBookingDate() == null) {
      return false;
    }
    
    Trip currentTrip = getTrip();
    
    // Step 2: Check number of seats
    if (getNumberOfSeats() <= 0 || getNumberOfSeats() > currentTrip.getNumberOfSeats()) {
      return false;
    }
    
    // Step 3: Parse trip departure and arrival times
    SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm");
    Date departureTime;
    Date arrivalTime;
    try {
      departureTime = sdf.parse(currentTrip.getDepartureTime());
      arrivalTime = sdf.parse(currentTrip.getArrivalTime());
    } catch (ParseException e) {
      return false;
    }
    
    // Step 4: Check if booking date is within 2 hours of departure
    long diffInMillis = departureTime.getTime() - getBookingDate().getTime();
    long twoHoursInMillis = 2 * 60 * 60 * 1000;
    if (diffInMillis <= twoHoursInMillis) {
      return false;
    }
    
    // Step 5: Check for overlapping bookings on the same day
    Calendar cal = Calendar.getInstance();
    cal.setTime(departureTime);
    int tripDay = cal.get(Calendar.DAY_OF_YEAR);
    int tripYear = cal.get(Calendar.YEAR);
    
    for (Booking b : getCustomer().getBookings()) {
      Trip bTrip = b.getTrip();
      if (bTrip != null) {
        try {
          Date bDeparture = sdf.parse(bTrip.getDepartureTime());
          Date bArrival = sdf.parse(bTrip.getArrivalTime());
          
          Calendar bCal = Calendar.getInstance();
          bCal.setTime(bDeparture);
          int bDay = bCal.get(Calendar.DAY_OF_YEAR);
          int bYear = bCal.get(Calendar.YEAR);
          
          // Check if on same calendar day
          if (bDay == tripDay && bYear == tripYear) {
            // Check for time overlap
            if (bDeparture.before(arrivalTime) && departureTime.before(bArrival)) {
              return false;
            }
          }
        } catch (ParseException e) {
          // Skip this booking if parsing fails
          continue;
        }
      }
    }
    
    // Step 6: All checks passed
    return true;
  }

