    Calendar cal = Calendar.getInstance();
    cal.setTime(getBookingDate());
    int bookingYear = cal.get(Calendar.YEAR);
    int bookingMonth = cal.get(Calendar.MONTH) + 1; // Calendar.MONTH is 0-based
    
    // Step 2: Parse the input month string
